// src/cli/main.cpp
#include <iostream>
#include <csignal>
#include <sys/stat.h>
#include <bpf/libbpf.h>
#include "common.h"
#include "recorder.skel.h" // Auto-generated by bpftool

static volatile bool keep_running = true;
void sig_handler(int) { keep_running = false; }

// Callback triggered every time the kernel pushes a socket_event
static int handle_event(void *ctx, void *data, size_t data_sz) {
    const auto *e = static_cast<const struct socket_event *>(data);
    std::cout << "[PID " << e->pid << " | FD " << e->fd << " | "
              << e->payload_len << " bytes]\n";

    // Print printable ASCII characters from the captured network packet
    for (unsigned int i = 0; i < e->payload_len; ++i) {
        char c = e->payload[i];
        std::cout << ((c >= 32 && c <= 126) || c == '\n' ? c : '.');
    }
    std::cout << "\n----------------------------------------\n";
    return 0;
}

int main(int argc, char **argv) {
    signal(SIGINT, sig_handler);

    // 1. Open eBPF skeleton
    struct recorder_bpf *skel = recorder_bpf__open();
    if (!skel) return 1;

    // Pass current PID namespace device & inode so PID filtering works in WSL2, Docker, and native Linux
    struct stat st;
    if (stat("/proc/self/ns/pid", &st) == 0) {
        skel->rodata->pidns_dev = st.st_dev;
        skel->rodata->pidns_ino = st.st_ino;
    }

    // Optional: Filter by PID passed on command line (./chronostap <PID>)
    if (argc > 1) {
        skel->rodata->target_pid = std::stoi(argv[1]);
    }

    // 2. Load & verify eBPF bytecode in the Linux Kernel, then attach hooks
    if (recorder_bpf__load(skel) || recorder_bpf__attach(skel)) {
        std::cerr << "Failed to load/attach eBPF recorder (Did you run with sudo?)\n";
        recorder_bpf__destroy(skel);
        return 1;
    }

    // 3. Poll the Ring Buffer
    struct ring_buffer *rb = ring_buffer__new(bpf_map__fd(skel->maps.rb), handle_event, nullptr, nullptr);
    std::cout << "[+] ChronosTap Wiretap active! Listening for socket traffic...\n";

    while (keep_running) {
        ring_buffer__poll(rb, 100 /* timeout ms */);
    }

    ring_buffer__free(rb);
    recorder_bpf__destroy(skel);
    return 0;
}